// Spike A benchmark: mif-rs WASM vs the TypeScript engine.
// Bundled with esbuild and run under Node (V8, the same engine as Obsidian
// desktop). Mobile numbers need an on-device run; see the report.
//   node spikes/mif-wasm/run-bench.mjs

import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { performance } from "node:perf_hooks";

// @ts-expect-error -- generated by wasm-pack, no types in the TS project
import init, * as wasm from "./pkg-web/mif_wasm.js";
import { mdToJsonLd, parseMarkdown, roundtripDrift } from "../../src/engine/convert";
import { validateJsonLd } from "../../src/engine/validate";

const ROOT = process.env.PLUGIN_ROOT!;
const median = (xs: number[]) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)]!;

function files(dir: string): string[] {
  return readdirSync(dir).flatMap((f) => {
    const p = join(dir, f);
    if (statSync(p).isDirectory()) return f.startsWith(".") || f.startsWith("_") ? [] : files(p);
    return f.endsWith(".md") && f !== "index.md" ? [p] : [];
  });
}

const docs = [...files(join(ROOT, "test-vault")), ...files(join(ROOT, "tests", "fixtures", "edge"))].map((p) => ({
  name: relative(ROOT, p),
  text: readFileSync(p, "utf8"),
}));

// ---- cold start -------------------------------------------------------------
const wasmBytes = readFileSync(join(ROOT, "spikes", "mif-wasm", "pkg-web", "mif_wasm_bg.wasm"));
const b64 = wasmBytes.toString("base64"); // what an inlined main.js would carry

let t = performance.now();
const decoded = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
const tDecode = performance.now() - t;
t = performance.now();
const module = new WebAssembly.Module(decoded);
const tCompile = performance.now() - t;
t = performance.now();
wasm.initSync({ module });
const tInstantiate = performance.now() - t;
void init;

const sample = docs.find((d) => d.name.endsWith("rate-limit-policy.md"))!.text;
t = performance.now();
wasm.validateJsonLd(wasm.toJsonLd(sample));
const tWasmFirstValidate = performance.now() - t;
t = performance.now();
validateJsonLd(mdToJsonLd(parseMarkdown(sample).frontmatter, parseMarkdown(sample).body));
const tTsFirstValidate = performance.now() - t;

// ---- warm per-op timings ----------------------------------------------------
const N = 2000;
function time(fn: () => unknown): number {
  for (let i = 0; i < 50; i++) fn();
  const xs: number[] = [];
  for (let i = 0; i < N; i++) {
    const s = performance.now();
    fn();
    xs.push(performance.now() - s);
  }
  return median(xs) * 1000; // µs
}

const sampleJsonLd = wasm.toJsonLd(sample) as string;
const tsParsed = parseMarkdown(sample);
const tsJsonLd = mdToJsonLd(tsParsed.frontmatter, tsParsed.body);
const ops = {
  parse: [() => wasm.parseMarkdown(sample), () => parseMarkdown(sample)],
  "md→JSON-LD": [() => wasm.toJsonLd(sample), () => { const p = parseMarkdown(sample); return mdToJsonLd(p.frontmatter, p.body); }],
  "round trip": [() => wasm.roundtripDrift(sample), () => roundtripDrift(sample)],
  validate: [() => wasm.validateJsonLd(sampleJsonLd), () => validateJsonLd(tsJsonLd)],
} as const;
const timings = Object.entries(ops).map(([op, [w, ts]]) => ({ op, wasm: time(w), ts: time(ts) }));

// ---- parity ----------------------------------------------------------------
type Outcome = { parse?: unknown; error?: string; jsonld?: unknown; drift?: string | null; schema?: number };
function viaWasm(text: string): Outcome {
  try {
    const parse = JSON.parse(wasm.parseMarkdown(text));
    const jsonldText = wasm.toJsonLd(text);
    return { parse, jsonld: JSON.parse(jsonldText), drift: wasm.roundtripDrift(text) ?? null, schema: wasm.validateJsonLd(jsonldText).length };
  } catch (e) {
    return { error: String((e as Error).message ?? e) };
  }
}
function viaTs(text: string): Outcome {
  try {
    const parse = parseMarkdown(text);
    const jsonld = JSON.parse(JSON.stringify(mdToJsonLd(parse.frontmatter, parse.body)));
    return { parse, jsonld, drift: roundtripDrift(text), schema: validateJsonLd(jsonld).length };
  } catch (e) {
    return { error: (e as Error).message };
  }
}
const diffKeys = (a: Record<string, unknown> = {}, b: Record<string, unknown> = {}) =>
  [...new Set([...Object.keys(a), ...Object.keys(b)])].filter((k) => JSON.stringify(a[k]) !== JSON.stringify(b[k]));

const parity = docs.map(({ name, text }) => {
  const w = viaWasm(text);
  const s = viaTs(text);
  const notes: string[] = [];
  if (w.error || s.error) {
    if (!(w.error && s.error)) notes.push(`only ${w.error ? "WASM" : "TS"} rejects: ${w.error ?? s.error}`);
  } else {
    const fmW = (w.parse as { frontmatter: Record<string, unknown> }).frontmatter;
    const fmS = (s.parse as { frontmatter: Record<string, unknown> }).frontmatter;
    const fmDiff = diffKeys(fmW, fmS);
    if (fmDiff.length) notes.push(`frontmatter differs: ${fmDiff.map((k) => `${k} wasm=${JSON.stringify(fmW[k])} ts=${JSON.stringify(fmS[k])}`).join("; ")}`);
    const jlDiff = diffKeys(w.jsonld as Record<string, unknown>, s.jsonld as Record<string, unknown>).filter((k) => !fmDiff.includes(k));
    if (jlDiff.length) notes.push(`JSON-LD differs: ${jlDiff.join(", ")}`);
    if ((w.drift === null) !== (s.drift === null)) notes.push(`round trip: wasm ${w.drift ? "lossy" : "lossless"}, ts ${s.drift ? "lossy" : "lossless"}`);
    if ((w.schema === 0) !== (s.schema === 0)) notes.push(`schema: wasm ${w.schema} issue(s), ts ${s.schema}`);
  }
  return { name, identical: notes.length === 0, notes };
});

console.log(JSON.stringify({
  sizes: {
    raw: wasmBytes.length,
    base64: b64.length,
  },
  coldMs: {
    base64Decode: tDecode,
    compile: tCompile,
    instantiate: tInstantiate,
    wasmFirstValidate: tWasmFirstValidate,
    tsFirstValidate: tTsFirstValidate,
  },
  warmMicros: timings,
  parity,
}, null, 2));
